float time;
#define FAR 100.
#define ID_NONE -1.


#define ID_GROUND 0.
#define ID_ART 1.
#define ID_HOUSE 2.
#define ID_CAR_RED 3.
#define ID_CAR_GREEN 4.
#define ID_CAR_BLUE 5.
#define ID_LAMP_COLUMN 6.
#define ID_LAMP_GLASS 7.
#define ID_ROAD 8.

float dfCar(vec3 p, float carDir) {
	float d1 = TF_BOX_ROUND(p-vec3(0,0.025,-carDir*0.04), vec3(0.05,0.025, 0.08), 0.02);
	float d2 = TF_BOX_ROUND(p-vec3(0,-0.025,0), vec3(0.1,0.03, 0.2), 0.02);
	return OR(d1, d2, 0.1);
}

float dfLonLanSphereGrid(vec3 p, float n, float R, float r) {
	vec3 q;
	float d;

	//Вертикальные торы
	q = p;
	TF_REPLICA_ANGLE(q.xz, n, 0.);		//Разбиваем пространстово .xz на n секторов
    TF_CYL(q.yz, R, 1.);				//Сворачиваем пространство .xz в цилиндр радиусом R 
	d = TF_BALL(q.xz, r);				//Протягиваем круглый профиль вдоль q.y

	//Горизонтальные торы
	q = p;
	TF_CYL(q.xz, 0., 1.);				//Сворачиваем пространство .xz в цилиндр радиусом 0 
	TF_REPLICA_ANGLE(q.yz, n, 0.);		//Разбиваем пространстово .yz на n секторов
	TF_TRANSLATE(q.z, R);				//Перемещаемся на радиус R
	float d1 = TF_BALL(q.yz, r);		//Протягиваем круглый профиль вдоль q.x

	return OR(d, d1);
}

Object Lamp(vec3 p) {
	vec3 q;
	float d;

	Object object = Object(FAR, ID_NONE, p);

	//Столбы
	Object OBJ1 = Object(FAR, ID_LAMP_COLUMN, p);
	{
		q = p;
		q.y -= -1.;
		d = TF_BOX_ROUND(q, vec3(0,2,0), 0.01);
		OBJ1.distance = d;
		OBJ1.position = p;
	}
	object = OR(object, OBJ1);

	//Плафоны
	Object OBJ2 = Object(FAR, ID_LAMP_GLASS, p);
	{
		q = p;
		q.y -= 1.;
		d = TF_BALL(q, 0.1);
		OBJ2.distance = d;
		OBJ2.position = p;
	}
	object = OR(object, OBJ2);

	return object;
}

//Свечение
float glow = 0.;
bool calcGlow = true;

float map(vec3 p, inout Object object){
	vec3 q;
	float d;

	vec3 p0 = p;

	object = Object(FAR, ID_NONE, p);

	//Земля
	Object OBJ0 = Object(FAR, ID_GROUND, p);
	{
		d = TF_BEFORE(p.y, 0.);
		OBJ0.distance = d;
		OBJ0.position = p;
	}
	object = OR(object, OBJ0);

	//Дорога на прямом участке
	Object OBJ1 = Object(FAR, ID_ROAD, p);
	{
		q = p;
		d = TF_BOX2D(q.xy, vec2(0.8, 0.05));
		OBJ1.distance = d;
		OBJ1.position = p;
	}
	object = AND(object, NOT(OBJ1));

	p = p0;
	TF_REPLICA(p.z, 20.);
	float carDir = sign(q.x); //Расположение автомобилей

	p.z = abs(p.z) - 2.8;
	p.x = abs(p.x) - 6.;

	//Зданиe
	Object OBJ2b = Object(FAR, ID_HOUSE, p);
	{
		q = p;
		q.x = abs(q.x) - 3.4;
		q.yz -= vec2(1.7,2.0);
		d = TF_BOX(q, vec3(0.75,2.5,1.00));
		OBJ2b.distance = d;
		OBJ2b.position = q;
	}
	object = OR(object, OBJ2b);

	//Зданиe
	Object OBJ2a = Object(FAR, ID_HOUSE, p);
	{
		q = p;
		q.x = abs(q.x) - 2.9;
		q.yz -= vec2(0.8,0.0);
		d = TF_BOX(q, vec3(0.65,2.5,0.70));
		OBJ2a.distance = d;
		OBJ2a.position = q;
	}
	object = OR(object, OBJ2a);

	//Зданиe
	Object OBJ2c = Object(FAR, ID_HOUSE, p);
	{
		q = p;
		q.x = abs(q.x) - 2.4;
		q.yz -= vec2(0.2,-1.5);
		d = TF_BOX(q, vec3(0.75,2.9,0.70));
		OBJ2c.distance = d;
		OBJ2c.position = q;
	}
	object = OR(object, OBJ2c);

	//Светильники
	p = p0;
	p.x = abs(p.x) - 3.;
	TF_REPLICA(p.z, 10.);
	p.x = abs(p.x) - 1.4;
	object = OR(object, Lamp(p));

	//Сфера
	Object OBJ3 = Object(FAR, ID_ART, p);
	{
		q = p0;
		q.z -= 10.;
		TF_REPLICA(q.z, 20.);
		q.x = abs(q.x) - 2.8;
		q.y -= 0.4;
		TF_ROTATE(q.xy, radians(20.));
		TF_ROTATE(q.xz, 0.7*u_time);
		d = dfLonLanSphereGrid(q, 15., 0.4, 0.01);
		OBJ3.distance = d;
		OBJ3.position = q;
	}
	object = OR(object, OBJ3);

	d = TF_BALL(q, 0.35);
	if (calcGlow && d<0.04) glow += +(0.01)/pow(OBJ3.distance, 1.);

	//Красные машины (прямой участок)
	Object OBJ4 = Object(FAR, ID_CAR_RED, p);
	{
		q = p0;
		q.z -= carDir * 2.*time;
		q.x = abs(q.x) - 0.55;
		q.y -= 0.1;
		TF_REPLICA(q.z, 10.);
		d = dfCar(q, carDir);
		OBJ4.distance = d;
		OBJ4.position = vec3(q.xy, carDir);
	}
	object = OR(object, OBJ4);

	//Зеленые машины (прямой участок)
	Object OBJ5 = Object(FAR, ID_CAR_GREEN, p);
	{
		q = p0;
		q.z -= carDir * (2.*time - 3.);
		q.x = abs(q.x) - 0.55;
		q.y -= 0.1;
		TF_REPLICA(q.z, 10.);
		d = dfCar(q, carDir);
		OBJ5.distance = d;
		OBJ5.position = vec3(q.xy, carDir);
	}
	object = OR(object, OBJ5);

	//Синие машины (прямой участок)
	Object OBJ6 = Object(FAR, ID_CAR_BLUE, p);
	{
		q = p0;
		q.z -= carDir * (2.8*time);
		q.x = abs(q.x) - 0.2;
		q.y -= 0.1;
		TF_REPLICA(q.z, 10.);
		d = dfCar(q, carDir);
		OBJ6.distance = d;
		OBJ6.position = vec3(q.xy, carDir);
	}
	object = OR(object, OBJ6);

	//Красные, зеленые и синие машины (на съездах)
	Object OBJ7 = Object(FAR, ID_CAR_RED, p);
	{
		q = p0;
		TF_REPLICA(q.z, 20.0);
		q.x = abs(q.x) - 10.6;
		TF_CYL(q.xz, 9.6, 2.);
		q.x -= carDir*2.*time;
		float id = TF_REPLICA(q.x, 2.*PI*10./10.);
		id = mod(id, 3.);

		q.y -= 0.1;
		d = dfCar(q.zyx, carDir);
		OBJ7.distance = d;
		OBJ7.position = vec3(q.zy, carDir);
		OBJ7.id += id;
	}
	object = OR(object, OBJ7);

	//Дорога на съездах	
	Object OBJ8 = Object(FAR, ID_ROAD, p);
	{
		q.y -= -0.1;
		d = TF_BOX2D(q.yz, vec2(0.05, 0.25));
		OBJ8.distance = d;
		OBJ8.position = q;
	}
	object = AND(object, NOT(OBJ8));

	return object.distance;
}

float map ( in vec3 p ) {
	Object object;
	return map (p, object);
}

vec3 mapNormal (vec3 p, float eps) {
	vec2 e = vec2 (eps, -eps);
	vec4 v = vec4 (
		map (p + e.xxx), 
		map (p + e.xyy),
	 	map (p + e.yxy), 
		map (p + e.yyx)
	);
	return normalize (vec3 (v.x - v.y - v.z - v.w) + 2. * vec3 (v.y, v.z, v.w));
}

float rayMarch(inout Ray ray) {
	ray.distance = ray.near;
	float steps;
	for (float i = 0.; i < 200.; ++i) {
		ray.position = ray.origin + ray.direction * ray.distance;
		ray.object.distance = map(ray.position, ray.object);
		ray.hit = abs(ray.object.distance) < ray.epsilon;
		if (ray.hit) break;
		ray.distance += ray.object.distance*ray.swing;
		if (ray.distance>ray.far) break;
		steps = i + 1.;
		if (steps>ray.steps) break;
	}
	return steps;
}

const vec3 sunDir = normalize(vec3(-0.5,2.5,2));

vec3 bgCol (vec3 rd, vec3 sunDir) {
	float sd = clamp (dot(sunDir, rd), 0., 1.);
	vec3 skyCol = mix(vec3 (0.5, 0.75, 1.), vec3(1), rd.y+0.2);
	float skyFactor = TF_SMOOTHSTEP_BEFORE(rd.y, -0.5, 0.2) * TF_SMOOTHSTEP_AFTER(rd.z, 0.0, 2.2);
	vec3 col = mix(vec3(0.10), skyCol*5., skyFactor);

	//Луна
	if (rd.z>0.) {
		vec3 moonColor = vec3(189, 208, 228)/255.;
		float c = 0.08/(length(rd.xy/0.5 - vec2(0.5)));
		col += smoothstep(0.,1.,pow(c,3.)) * moonColor;
	}
	return col;
}

vec3 lighting(Ray ray, vec3 ltPos, vec4 mat) {
	vec3 ltDir = normalize(ltPos-ray.position);
	float ltDist = length(ltPos-ray.position);
	float att = 1.0/pow(ltDist,2.);
	float sh = 1.;
	float diff = max(dot(ray.normal,ltDir),0.0);
	float spec = pow (max (dot (ltDir, reflect (ray.direction, ray.normal)), 0.), 64.);
	vec3 col;
	if (mat.a>=0.) {
		col = mat.rgb*(0.35 + 0.65 * diff * att * sh) + mat.a*spec * att * sh;
	} else {
		col = mat.rgb;
	}
	return col;
}


vec4 getMaterial(Ray ray) {
	vec3 mCol;
	float mSpec = 1.5;
	vec3 p = ray.position;
	vec3 q = ray.object.position;
	vec3 n = ray.normal;
	if (ray.object.id==ID_GROUND) {
		mCol=vec3(0.9);
		mSpec = 0.;
	} else if(ray.object.id == ID_ROAD) {
		mCol=vec3(0.6);
		mSpec = 0.3;
		if(TF_BETWEEN(p.x, 1.)<0.){
			vec3 pp = p;
			pp.x = abs(pp.x)-0.05;
		  	if(TF_BETWEEN(pp.x, 0.015)<0.){
				mSpec = 2.8;
				mCol=vec3(1,1,0)*2.;
			}
			pp = p;
			pp.x = abs(pp.x)-0.65;
			TF_REPLICA(pp.z, 1.);
			pp.x = abs(pp.x)-0.20;
		  	if(TF_BOX2D(pp.xz, vec2(0.015, 0.35))<0.){
				mSpec = 2.8;
				mCol=vec3(1)*1.5;
			}
		}
	} else if(ray.object.id == ID_ART) {
		mCol=vec3(1);
	} else if(ray.object.id == ID_HOUSE) {
		vec2 id = TF_REPLICA(q.yz, 0.3);
		float rnd = fract(sin(dot(id + vec2(111, 73), vec2(7.63, 157.31)))*4832.3234);
		bool isWindow = TF_BOX2D(q.yz, 0.05)<0.;
		vec3 winColor; 
		if (rnd<0.25) {
			winColor = vec3(0.6,0.8,0.8)*2.;
		} else if (rnd<0.5) {
			winColor = vec3(0.8,0.8,0.6)*2.;
		} else if (rnd<0.75) {
			winColor = vec3(0.8,0.8,0.6)*1.5;
		} else {
			winColor = vec3(0.6);
		}
		mCol = isWindow ? winColor : vec3(0.4);
		mSpec = isWindow ? 2.0: 0.2;
	} else if(ray.object.id == ID_CAR_RED) {
		mCol = vec3(0.4 + 0.6,0.35,0.4);
	} else if(ray.object.id == ID_CAR_GREEN) {
		mCol = vec3(0.4,0.35+0.65,0.4);
	} else if(ray.object.id == ID_CAR_BLUE) {
		mCol = vec3(0.5,0.5,1.);
	} else if(ray.object.id == ID_LAMP_COLUMN) {
		mCol = vec3(0.2,0.2,0.2);
	} else if(ray.object.id == ID_LAMP_GLASS) {
		mCol = vec3(2);
		mSpec = -1.;
	}
	if (ray.object.id == ID_CAR_RED || ray.object.id == ID_CAR_GREEN || ray.object.id == ID_CAR_BLUE) {
		vec3 qq = q;
		float carDir = q.z;
		qq.x = abs(qq.x)-0.07;
		qq.y -= -0.03;
		if (TF_BALL(qq.xy, 0.02)<0.) {
			if (n.z*carDir>0.) {
				mCol = vec3(2);
			} else {
				mCol = vec3(2,0,0);
			}
			mSpec = -1.;
		}
		qq = q;
		if (TF_BETWEEN2(qq.y, 0.03, 0.065)<0.) {
			mCol = vec3(0.2,0.2,0.2);
		}
	}
	return vec4(mCol, mSpec);
}

vec3 render(Ray ray) {
	vec3 col;
	vec3 bgColor = bgCol(ray.direction, sunDir);

	calcGlow = true;
	rayMarch(ray);

	if(ray.distance<FAR){
		calcGlow = false;
		ray.normal = mapNormal(ray.position, 0.001);
		vec4 mat = getMaterial(ray);

		ray.position.x = abs(ray.position.x) - 3.;
		TF_REPLICA(ray.position.z, 10.);
		ray.position.x = abs(ray.position.x) - 1.4;
		vec3 ltPos = vec3(0,1.0,0.0);

		col = lighting(ray, ltPos, mat);
		//Туман
		float fogStart = 25.;
		vec3 fogColor = bgColor;
		col = mix(col, fogColor, clamp((ray.distance-fogStart)/(50.-fogStart), 0., 1.));

	} else {
		col = bgColor;
	}

	col += (0.28) * glow * vec3 (0.2, 0.4, 1.);

	return col;
}

